1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/peripherals/ziptimer.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	A lighter weight implementation of the Zip Timer.
8	//
9	// Interface:
10	//	Two options:
11	//	1. One combined register for both control and value, and ...
12	//		The reload value is set any time the timer data value is "set".
13	//		Reading the register returns the timer value.  Controls are
14	//		set so that writing a value to the timer automatically starts
15	//		it counting down.
16	//	2. Two registers, one for control one for value.
17	//		The control register would have the reload value in it.
18	//	On the clock when the interface is set to zero the interrupt is set.
19	//		Hence setting the timer to zero will disable the timer without
20	//		setting any interrupts.  Thus setting it to five will count
21	//		5 clocks: 5, 4, 3, 2, 1, Interrupt.
22	//
23	//
24	//	Control bits:
25	//		(Start_n/Stop.  This bit has been dropped.  Writing to this
26	//			timer any value but zero starts it.  Writing a zero
27	//			clears and stops it.)
28	//		AutoReload.  If set, then on reset the timer automatically
29	//			loads the last set value and starts over.  This is
30	//			useful for distinguishing between a one-time interrupt
31	//			timer, and a repetitive interval timer.
32	//		(INTEN.  Interrupt enable--reaching zero always creates an
33	//			interrupt, so this control bit isn't needed.  The
34	//			interrupt controller can be used to mask the interrupt.)
35	//		(COUNT-DOWN/UP: This timer is *only* a count-down timer.
36	//			There is no means of setting it to count up.)
37	//	WatchDog
38	//		This timer can be implemented as a watchdog timer simply by
39	//		connecting the interrupt line to the reset line of the CPU.
40	//		When the timer then expires, it will trigger a CPU reset.
41	//
42	//
43	// Creator:	Dan Gisselquist, Ph.D.
44	//		Gisselquist Technology, LLC
45	//
46	////////////////////////////////////////////////////////////////////////////////
47	// }}}
48	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
49	// {{{
50	// This program is free software (firmware): you can redistribute it and/or
51	// modify it under the terms of the GNU General Public License as published
52	// by the Free Software Foundation, either version 3 of the License, or (at
53	// your option) any later version.
54	//
55	// This program is distributed in the hope that it will be useful, but WITHOUT
56	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
57	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
58	// for more details.
59	//
60	// You should have received a copy of the GNU General Public License along
61	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
62	// target there if the PDF file isn't present.)  If not, see
63	// <http://www.gnu.org/licenses/> for a copy.
64	// }}}
65	// License:	GPL, v3, as defined and found on www.gnu.org,
66	// {{{
67	//		http://www.gnu.org/licenses/gpl.html
68	//
69	////////////////////////////////////////////////////////////////////////////////
70	//
71	`default_nettype	none
72	// }}}
73	module	ziptimer #(
74			// {{{
75			parameter	BW = 32, VW = (BW-1),
76			parameter [0:0]	RELOADABLE = 1
77			// }}}
78		) (
79			// {{{
80			input	wire		i_clk, i_reset, i_ce,
81			// Wishbone inputs
82			input	wire		i_wb_cyc, i_wb_stb, i_wb_we,
83			input	wire [BW-1:0]	i_wb_data,
84			input	wire [BW/8-1:0]	i_wb_sel,
85			// Wishbone outputs
86			output	wire		o_wb_stall,
87			output	reg		o_wb_ack,
88			output	wire [BW-1:0]	o_wb_data,
89			// Interrupt line
90			output	reg		o_int
91			// }}}
92		);
93	
94		// Local declarations
95		// {{{
96		reg			r_running;
97		reg			r_zero  = 1'b1;
98		reg	[(VW-1):0]	r_value;
99	
100		wire	wb_write;
101	
102		wire			auto_reload;
103		wire	[(VW-1):0]	interval_count;
104		// }}}
105	
106		assign	wb_write = ((i_wb_stb)&&(i_wb_we));
107	
108		// r_running
109		// {{{
110		initial	r_running = 1'b0;
111		always @(posedge i_clk)
112		if (i_reset)
113			r_running <= 1'b0;
114		else if (wb_write)
115			r_running <= (|i_wb_data[(VW-1):0]);
116		else if ((r_zero)&&(!auto_reload))
117			r_running <= 1'b0;
118		// }}}
119	
120		// r_auto_reload, r_interval_count
121		// {{{
122		generate
123		if (RELOADABLE != 0)
124		begin : GEN_RELOAD
125			// {{{
126			reg			r_auto_reload;
127			reg	[(VW-1):0]	r_interval_count;
128	
129			// r_auto_reload
130			// {{{
131			initial	r_auto_reload = 1'b0;
132			always @(posedge i_clk)
133			if (i_reset)
134				r_auto_reload <= 1'b0;
135			else if (wb_write)
136				r_auto_reload <= (i_wb_data[(BW-1)])
137						&&(|i_wb_data[(VW-1):0]);
138			// }}}
139	
140			assign	auto_reload = r_auto_reload;
141	
142			// r_interval_count
143			// {{{
144			// If setting auto-reload mode, and the value to other
145			// than zero, set the auto-reload value
146			always @(posedge i_clk)
147			if (i_reset)
148				r_interval_count <= 0;
149			else if (wb_write)
150				r_interval_count <= i_wb_data[(VW-1):0];
151			// }}}
152	
153			assign	interval_count = r_interval_count;
154			// }}}
155		end else begin : NO_AUTO_RELOAD
156			// {{{
157			assign	auto_reload = 1'b0;
158			assign	interval_count = 0;
159			// }}}
160		end endgenerate
161		// }}}
162	
163		// r_value
164		// {{{
165		initial	r_value = 0;
166		always @(posedge i_clk)
167		if (i_reset)
168			r_value <= 0;
169		else if (wb_write)
170			r_value <= i_wb_data[(VW-1):0];
171		else if ((i_ce)&&(r_running))
172		begin
173			if (!r_zero)
174				r_value <= r_value - 1'b1;
175			else if (auto_reload)
176				r_value <= interval_count;
177		end
178		// }}}
179	
180		// r_zero
181		// {{{
182		always @(posedge i_clk)
183		if (i_reset)
184			r_zero <= 1'b1;
185		else if (wb_write)
186			r_zero <= (i_wb_data[(VW-1):0] == 0);
187		else if ((r_running)&&(i_ce))
188		begin
189			if (r_value == { {(VW-1){1'b0}}, 1'b1 })
190				r_zero <= 1'b1;
191			else if ((r_zero)&&(auto_reload))
192				r_zero <= 1'b0;
193		end
194		// }}}
195	
196		// o_int
197		// {{{
198		// Set the interrupt on our last tick, as we transition from one to
199		// zero.
200		initial	o_int   = 1'b0;
201		always @(posedge i_clk)
202		if ((i_reset)||(wb_write)||(!i_ce))
203			o_int <= 1'b0;
204		else // if (i_ce)
205			o_int <= (r_value == { {(VW-1){1'b0}}, 1'b1 });
206		// }}}
207	
208		// o_wb_ack
209		// {{{
210		initial	o_wb_ack = 1'b0;
211		always @(posedge i_clk)
212			o_wb_ack <= (!i_reset)&&(i_wb_stb);
213		// }}}
214		assign	o_wb_stall = 1'b0;
215	
216		// o_wb_data
217		// {{{
218		generate if (VW < BW-1)
219		begin : GEN_TRIM
220			assign	o_wb_data = { auto_reload, {(BW-1-VW){1'b0}}, r_value };
221		end else begin : NO_TRIM
222			assign	o_wb_data = { auto_reload, r_value };
223		end endgenerate
224		// }}}
225	
226		// Make verilator happy
227		// {{{
228		// verilator coverage_off
229		// verilator lint_off UNUSED
230		wire	unused;
231		assign	unused = &{ 1'b0, i_wb_cyc, i_wb_data, i_wb_sel };
232		// verilator lint_on  UNUSED
233		// verilator coverage_on
234		// }}}
235	////////////////////////////////////////////////////////////////////////////////
236	////////////////////////////////////////////////////////////////////////////////
237	////////////////////////////////////////////////////////////////////////////////
238	//
239	// Formal properties
240	// {{{
241	////////////////////////////////////////////////////////////////////////////////
242	////////////////////////////////////////////////////////////////////////////////
243	////////////////////////////////////////////////////////////////////////////////
244	`ifdef	FORMAL
245		reg	f_past_valid;
246		initial	f_past_valid = 1'b0;
247		always @(posedge i_clk)
248			f_past_valid <= 1'b1;
249	
250		initial	assume(i_reset);
251		always @(*)
252		if (!f_past_valid)
253			assume(i_reset);
254	
255		always @(posedge i_clk)
256		if ((!f_past_valid)||($past(i_reset)))
257		begin
258			assert(r_value     == 0);
259			assert(r_running   == 0);
260			assert(auto_reload == 0);
261			assert(r_zero      == 1'b1);
262		end
263	
264	
265		always @(*)
266		if (i_wb_stb)
267			assume(i_wb_cyc);
268	
269		always @(*)
270			assert(r_zero == (r_value == 0));
271	
272		always @(*)
273		if (r_value != 0)
274			assert(r_running);
275	
276		always @(*)
277		if (auto_reload)
278			assert(r_running);
279	
280		always @(*)
281		if (!RELOADABLE)
282			assert(auto_reload == 0);
283	
284		always @(*)
285		if (auto_reload)
286			assert(interval_count != 0);
287	
288		always @(posedge i_clk)
289		if ((f_past_valid)&&($past(r_value)==0)
290				&&(!$past(wb_write))&&(!$past(auto_reload)))
291			assert(r_value == 0);
292	
293		always @(posedge i_clk)
294		if ((f_past_valid)&&(!$past(i_reset))&&(!$past(wb_write))
295				&&($past(r_value)==0)&&($past(auto_reload)))
296		begin
297			if ($past(i_ce))
298			begin
299				assert(r_value == interval_count);
300			end else
301				assert(r_value == $past(r_value));
302		end
303	
304		always @(posedge i_clk)
305		if ((f_past_valid)&&(!$past(i_reset))
306				&&(!$past(wb_write))&&($past(r_value)!=0))
307		begin
308			if ($past(i_ce))
309			begin
310				assert(r_value == $past(r_value)-1'b1);
311			end else
312				assert(r_value == $past(r_value));
313		end
314	
315		always @(posedge i_clk)
316		if ((f_past_valid)&&(!$past(i_reset))&&($past(wb_write)))
317			assert(r_value == $past(i_wb_data[(VW-1):0]));
318	
319		// Check auto_reload
320		// {{{
321		always @(posedge i_clk)
322		if (!f_past_valid || $past(i_reset) || !RELOADABLE)
323		begin
324			assert(!auto_reload);
325		end else if ($past(wb_write))
326		begin
327			if (!$past(i_wb_data[BW-1]))
328			begin
329				assert(!auto_reload);
330			end else
331				assert(auto_reload == $past(|i_wb_data[VW-1:0]));
332		end else
333			assert($stable(auto_reload));
334		// }}}
335	
336		always @(posedge i_clk)
337		if (!(f_past_valid)||($past(i_reset)))
338		begin
339			assert(!o_int);
340		end else if (($past(wb_write))||(!$past(i_ce)))
341		begin
342			assert(!o_int);
343		end else
344			assert(o_int == ((r_running)&&(r_value == 0)));
345	
346		always @(posedge i_clk)
347		if ((!f_past_valid)||($past(i_reset)))
348		begin
349			assert(!o_wb_ack);
350		end else if ($past(i_wb_stb))
351			assert(o_wb_ack);
352	
353		always @(*)
354			assert(!o_wb_stall);
355		always @(*)
356			assert(o_wb_data[BW-1] == auto_reload);
357		always @(*)
358			assert(o_wb_data[VW-1:0] == r_value);
359	`endif
360	// }}}
361	endmodule
