// {{{
//		http://www.gnu.org/licenses/gpl.html
//
////////////////////////////////////////////////////////////////////////////////
//
`default_nettype	none
// }}}
module	zipjiffies #(
		parameter	BW = 32
	) (
		// {{{
		input	wire			i_clk, i_reset, i_ce,
		// Wishbone inputs
		input	wire			i_wb_cyc, i_wb_stb, i_wb_we,
		input	wire	[(BW-1):0]	i_wb_data,
		input	wire	[BW/8-1:0]	i_wb_sel,
		// Wishbone outputs
		output	wire			o_wb_stall,
		output	reg			o_wb_ack,
		output	wire	[(BW-1):0]	o_wb_data,
		// Interrupt line
		output	reg			o_int
		// }}}
	);

	// Local declarations
	// {{{
	reg	[(BW-1):0]		r_counter;
	//
	reg				int_set,  new_set, int_now;
	reg		[(BW-1):0]	int_when, new_when;
	reg	signed	[(BW-1):0]	till_wb,  till_when;
	// }}}

	// r_counter
	// {{{
	// Our counter logic: The counter is always counting up--it cannot
	// be stopped or altered.  It's really quite simple.  Okay, not quite.
	// We still support the clock enable line.  We do this in order to
	// support debugging, so that if we get everything running inside a
	// debugger, the timer's all slow down so that everything can be stepped
	// together, one clock at a time.
	//
	initial	r_counter = 0;
	always @(posedge i_clk)
	if (i_reset)
		r_counter <= 0;
	else if (i_ce)
		r_counter <= r_counter+1;
	// }}}

	// int_now
	// {{{
	initial	int_now = 0;
	always @(posedge i_clk)
	if (i_reset)
		int_now <= 0;
	else if (i_ce)
		int_now <= ((r_counter + 1) == (int_when));
	else
		int_now <= 1'b0;
	// }}}

	// new_set, new_when
	// {{{
	// Writes to the counter set an interrupt--but only if they are in the
	// future as determined by the signed result of an unsigned subtract.
	//
	// assign	till_when = int_when-r_counter;
	// assign	till_wb   = new_when-r_counter;

	initial	new_set = 1'b0;
	always @(posedge i_clk)
	begin
		// Delay WB commands (writes) by a clock to simplify our logic
		new_set <= (i_wb_stb && i_wb_we);
		// new_when is a don't care when new_set = 0, so don't worry
		// about setting it at all times.
		new_when<= i_wb_data;

		till_wb <= (i_wb_data - r_counter - (i_ce ? 1:0));

		till_when <= (int_when - i_wb_data);

		if (i_reset)
			new_set <= 1'b0;
	end
	// }}}

	// o_int, int_set
	// {{{
	initial	o_int   = 1'b0;
	initial	int_set = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
	begin
		// {{{
		o_int <= 0;
		int_set <= 0;
		// }}}
	end else begin
		// {{{
		o_int <= 1'b0;
		if ((i_ce)&&(int_set)&&(r_counter == int_when))
			// Interrupts are self-clearing
			o_int <= 1'b1;	// Set the interrupt flag for one clock
		else if ((new_set)&&(till_wb <= 0))
			o_int <= 1'b1;

		if ((new_set)&&(till_wb > 0))
			int_set <= 1'b1;
		else if (int_now)
			int_set <= 1'b0;
		// }}}
	end
	// }}}

	// int_when
	// {{{
	always @(posedge i_clk)
	if ((new_set)&&(till_wb > 0)&&((till_when[BW-1])||(!int_set)))
		int_when <= new_when;
	// }}}

	// o_wb_ack
	// {{{
	// Acknowledge any wishbone accesses -- everything we did took only
	// one clock anyway.
	//
	initial	o_wb_ack = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		o_wb_ack <= 1'b0;
	else
		o_wb_ack <= i_wb_stb;
	// }}}

	assign	o_wb_data = r_counter;
	assign	o_wb_stall = 1'b0;

	// Make verilator happy
	// {{{
	// verilator coverage_off
	// verilator lint_off UNUSED
	wire	unused;
	assign	unused = &{ 1'b0, i_wb_cyc, i_wb_sel };
	// verilator lint_on  UNUSED
	// verilator coverage_on
	// }}}
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
//
// Formal properties
// {{{
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
`ifdef	FORMAL
	reg	f_past_valid;
	initial	f_past_valid = 1'b0;
	always @(posedge i_clk)
		f_past_valid <= 1'b1;

	////////////////////////////////////////////////////////////////////////
	//
	// Assumptions about our inputs
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	// One basic WB assumtion

	// Anytime the stb is high, the cycle line must also be high
	always @(posedge i_clk)
		assume((!i_wb_stb)||(i_wb_cyc));
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Assertions about our bus outputs
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	// We never stall the bus
	always @(*)
		assert(!o_wb_stall);

	// We always ack every transaction on the following clock
	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&($past(i_wb_stb)))
	begin
		assert(o_wb_ack);
	end else
		assert(!o_wb_ack);
	// }}}
	///////////////////////////////////////////////////////////////////////
	//
	// Assumptions about our internal state and our outputs
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	always @(posedge i_clk)
	if ((f_past_valid)&&($past(i_reset)))
	begin
		assert(!o_wb_ack);
	end

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&($past(i_wb_stb))
			&&($past(i_wb_we)))
		assert(new_when == $past(i_wb_data));

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&($past(i_wb_stb))
			&&($past(i_wb_we)))
	begin
		assert(new_set);
	end else
		assert(!new_set);

	//
	//
	//

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(i_reset)))
		assert(!o_int);

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(i_reset)))
	begin
		assert(!int_set);
		assert(!new_set);
	end

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&($past(new_set))
			&&(!$past(till_wb[BW-1]))
			&&($past(till_wb) > 0))
		assert(int_set);

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&($past(i_ce))
		&&($past(r_counter)==$past(int_when)))
	begin
		assert((o_int)||(!$past(int_set)));
		// assert((!int_set)||($past(new_set)));	// !!!!!
	end

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&(!$past(new_set))&&(!$past(int_set)))
		assert(!int_set);

	always @(posedge i_clk)
	if ((!f_past_valid)||($past(i_reset)))
	begin
		assert(!o_int);
	end else if (($past(new_set))&&($past(till_wb) < 0))
		assert(o_int);

	always @(posedge i_clk)
	if ((f_past_valid)&&
			((!$past(new_set))
			||($past(till_wb[BW-1]))
			||($past(till_wb == 0))))
		assert(int_when == $past(int_when));
	// }}}
`endif
// }}}
endmodule

////////////////////////////////////////////////////////////////////////////////
//
// Filename:	rtl/peripherals/wbwatchdog.v
// {{{
// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
//
// Purpose:	A Zip timer, redesigned to be a bus watchdog
//
//	This is basically a timer, but there are some unique features to it.
//
//	1. There is no way to "write" the timeout to this watchdog.  It is
//		fixed with an input (that is assumed to be constant)
//	2. The counter returns to i_timer and the interrupt is cleared on any
//		reset.
//	3. Between resets, the counter counts down to zero.  Once (and if) it
//		hits zero, it will remain at zero until reset.
//	4. Any time the counter is at zero, and until the reset that resets
//		the counter, the output interrupt will be set.
//
//
// Creator:	Dan Gisselquist, Ph.D.
//		Gisselquist Technology, LLC
//
////////////////////////////////////////////////////////////////////////////////
// }}}
// Copyright (C) 2015-2025, Gisselquist Technology, LLC
// {{{
// This program is free software (firmware): you can redistribute it and/or
// modify it under the terms of the GNU General Public License as published
// by the Free Software Foundation, either version 3 of the License, or (at
// your option) any later version.
//
// This program is distributed in the hope that it will be useful, but WITHOUT
// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
// for more details.
//
// You should have received a copy of the GNU General Public License along
// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
// target there if the PDF file isn't present.)  If not, see
// <http://www.gnu.org/licenses/> for a copy.
// }}}
// License:	GPL, v3, as defined and found on www.gnu.org,
// {{{
//		http://www.gnu.org/licenses/gpl.html
//
////////////////////////////////////////////////////////////////////////////////
//
`default_nettype	none
// }}}
module	wbwatchdog #(
		parameter	BW = 32
	) (
		// {{{
		input	wire		i_clk, i_reset,
		// Inputs (these were at one time wishbone controlled ...)
		input	wire [(BW-1):0]	i_timeout,
		// Interrupt line
		output	reg		o_int
		// }}}
	);

	reg	[(BW-1):0]	r_value;

	// r_value
	// {{{
	initial	r_value = {(BW){1'b1}};
	always @(posedge i_clk)
	if (i_reset)
		r_value <= i_timeout[(BW-1):0];
	else if (!o_int)
		r_value <= r_value + {(BW){1'b1}}; // r_value - 1;
	// }}}

	// Set the interrupt on our last tick.
	// {{{
	initial	o_int   = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		o_int <= 1'b0;
	else if (!o_int)
		o_int <= (r_value == { {(BW-1){1'b0}}, 1'b1 });
	// }}}
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
//
// Formal properties
// {{{
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
`ifdef	FORMAL
	reg	f_past_valid;

	initial	f_past_valid = 1'b0;
	always @(posedge i_clk)
		f_past_valid <= 1'b1;

	////////////////////////////////////////////////////////////////////////
	//
	// Assumptions about our inputs
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	always @(*)
		assume(i_timeout > 1);

	always @(posedge i_clk)
	if (f_past_valid)
		assume(i_timeout == $past(i_timeout));
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Assertions about our internal state and our outputs
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_int))&&(!$past(i_reset)))
		assert(o_int);

	always @(*)
		assert(o_int == (r_value == 0));

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&(!$past(o_int)))
	begin
		assert(r_value == $past(r_value)-1'b1);
	end

	always @(posedge i_clk)
	if ((!f_past_valid)||($past(i_reset)))
	begin
		if (!f_past_valid)
		begin
			assert(r_value == {(BW){1'b1}});
		end else // if ($past(i_reset))
			assert(r_value == $past(i_timeout));
		assert(!o_int);
	end
	// }}}
`endif
// }}}
endmodule

