		//
		// Master task counter
		zipcounter
		mtask_ctr(
			// {{{
			i_clk, 1'b0, (!cmd_halt), sys_cyc,
			(sys_stb)&&(sel_counter)&&(sys_addr[2:0] == 3'b000),
				sys_we, sys_data,
