zipcounter
utask_ctr(
	// {{{
	i_clk,1'b0, (!cmd_halt)&&(cpu_gie), sys_cyc,
	(sys_stb)&&(sel_counter)&&(sys_addr[2:0] == 3'b100),
		sys_we, sys_data,
	utc_stall, utc_ack, utc_data, utc_int
	// }}}
);

