		end

	end endgenerate

	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Timers
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	// Timer A
	//
	ziptimer u_timer_a(
