		.i_clk(i_clk), .i_reset(cpu_reset), .i_ce(!cmd_halt),
		.i_wb_cyc(sys_cyc),
		.i_wb_stb((sys_stb)&&(sel_timer)&&(sys_addr[1:0] == 2'b01)),
